import type { Language } from '@/data/types';

/**
 * Worker-mode strings. Kept short, concrete and icon-backed so they work for people who
 * read slowly or prefer another language. Task titles generated by ROOST are translated too.
 */
const STRINGS = {
  en: {
    morning: 'Good morning', afternoon: 'Good afternoon', evening: 'Good evening',
    eggs: 'Eggs', feed: 'Feed', water: 'Water', losses: 'Losses', note: 'Note',
    myTasks: 'My tasks today', allDone: 'All done. Thank you!', hold: 'Hold to exit worker mode', language: 'Language',
    left: (n: number) => `${n} left`,
  },
  sw: {
    morning: 'Habari za asubuhi', afternoon: 'Habari za mchana', evening: 'Habari za jioni',
    eggs: 'Mayai', feed: 'Chakula', water: 'Maji', losses: 'Waliopotea', note: 'Ujumbe',
    myTasks: 'Kazi zangu leo', allDone: 'Umemaliza. Asante!', hold: 'Shikilia kutoka', language: 'Lugha',
    left: (n: number) => `${n} zimebaki`,
  },
  fr: {
    morning: 'Bonjour', afternoon: 'Bon après-midi', evening: 'Bonsoir',
    eggs: 'Œufs', feed: 'Aliment', water: 'Eau', losses: 'Pertes', note: 'Note',
    myTasks: 'Mes tâches du jour', allDone: 'Tout est fait. Merci !', hold: 'Maintenir pour quitter', language: 'Langue',
    left: (n: number) => `${n} restantes`,
  },
} as const;

const TASKS: Record<string, { sw: string; fr: string }> = {
  'Collect eggs': { sw: 'Kusanya mayai', fr: 'Ramasser les œufs' },
  'Morning feed': { sw: 'Chakula cha asubuhi', fr: 'Repas du matin' },
  'Check drinkers and water meter': { sw: 'Kagua vinywesheo na mita ya maji', fr: 'Vérifier abreuvoirs et compteur' },
  'Check drinkers': { sw: 'Kagua vinywesheo', fr: 'Vérifier les abreuvoirs' },
  'Bring birds in and lock up': { sw: 'Rudisha kuku bandani na funga', fr: 'Rentrer les volailles et fermer' },
  'Biosecurity walk-round': { sw: 'Ukaguzi wa usafi na usalama', fr: 'Tour de biosécurité' },
  'Electrolytes in water': { sw: 'Weka elektrolaiti kwenye maji', fr: 'Électrolytes dans l’eau' },
  'Check egg turning': { sw: 'Kagua ugeuzaji wa mayai', fr: 'Vérifier le retournement des œufs' },
  'Newcastle booster': { sw: 'Chanjo ya kuongeza ya Newcastle', fr: 'Rappel Newcastle' },
};

export function t(lang: Language) {
  return STRINGS[lang];
}

export function taskTitle(title: string, lang: Language) {
  if (lang === 'en') return title;
  return TASKS[title]?.[lang] ?? title;
}

export const LANGUAGES: { key: Language; label: string }[] = [
  { key: 'en', label: 'English' },
  { key: 'sw', label: 'Kiswahili' },
  { key: 'fr', label: 'Français' },
];
